#include <stdio.h>
#include <stdlib.h>

#define INF 1000000000

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *a = (int *)malloc(n * sizeof(int));
    int *ans = (int *)malloc(n * sizeof(int));

    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    // Passada da esquerda para a direita
    int current = INF;
    for (int i = 0; i < n; i++) {
        if (current < INF) {
            current++;
        }
        if (a[i] != -1) {
            if (a[i] < current) {
                current = a[i];
            }
        }
        ans[i] = current;
    }

    // Passada da direita para a esquerda
    current = INF;
    for (int i = n - 1; i >= 0; i--) {
        if (current < INF) {
            current++;
        }
        if (a[i] != -1) {
            if (a[i] < current) {
                current = a[i];
            }
        }
        if (current < ans[i]) {
            ans[i] = current;
        }
    }

    for (int i = 0; i < n; i++) {
        printf("%d%c", ans[i], (i == n - 1) ? '\n' : ' ');
    }

    free(a);
    free(ans);

    return 0;
}
